import '@testing-library/jest-dom/vitest'
import { render, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import { FamilyCaseProgress } from './FamilyCaseProgress'

describe('FamilyCaseProgress', () => {
  it('shows plain steps with doctor review current and no agent names', () => {
    render(<FamilyCaseProgress caseStatus="PendingDoctorReview" />)
    expect(screen.getByText('Doctor review').closest('li')).toHaveAttribute('aria-current', 'step')
    expect(screen.queryByText(/agent|coordinator/i)).not.toBeInTheDocument()
  })

  it('defers to in-person care when the case stopped', () => {
    render(<FamilyCaseProgress caseStatus="FailedSafe" />)
    expect(screen.getByRole('status')).toHaveTextContent('in-person clinical review')
  })
})
